<style>.contact-result{max-width:760px;padding:42px;border:1px solid var(--border);border-radius:28px;background:#fff;text-align:center;box-shadow:var(--shadow-elegant)}.contact-result-mark{width:64px;height:64px;display:grid;place-items:center;margin:0 auto 20px;border-radius:50%;background:rgba(145,208,37,.16);color:var(--primary-deep);font-size:29px}.contact-result p{color:var(--muted-foreground);font-size:17px}</style><section class="hero"><div class="wrap"><h1><?= e($title) ?></h1></div></section><section class="content"><div class="wrap"><div class="contact-result"><div class="contact-result-mark"><?=!empty($success)?'✓':'!'?></div><p><?= e($message) ?></p><a class="btn" href="/idemaclima/contatti">Torna ai contatti</a></div></div></section>
